data.action:
var time = 60*5;
cafeteria_foods = [
	{id:"regen_stamina", eat:function(player){player.stats.get("regen_stamina").tempBuff(25, time);}},
	{id:"mine", eat:function(player){player.stats.get("mine").tempBuff(3, time);}},
	{id:"toxic", eat:function(player){player.stats.get("regen_health").tempBuff(-5, 60);}},
	{id:"light", eat:function(player){player.stats.get("light").tempBuff(1, time);}},
	{id:"regen_power", eat:function(player){player.stats.get("regen_power").tempBuff(50, time);}},
	{id:"regen_health", eat:function(player){player.stats.get("regen_health").tempBuff(5, time);}},
	{id:"endurance", eat:function(player){player.stats.get("endurance").tempBuff(10, time);}},
	{id:"attack", eat:function(player){player.stats.get("attack").tempBuff(3, time);}},
	{id:"bargaining", eat:function(player){player.stats.get("bargaining").tempBuff(5, time);}},
	{id:"oxygen", eat:function(player){player.stats.get("oxygen").tempBuff(100, time);}},
	{id:"knock_out", eat:function(player){player.stats.get("endurance").tempBuff(-10, 60);}},
	{id:"farsight", eat:function(player){player.stats.get("sight").tempBuff(1, time); player.stats.get("evasion").tempBuff(10, time);}},
	{id:"porky", eat:function(player){player.stats.get("speed").tempBuff(-1, time); player.stats.get("weight").tempBuff(100, time);}},
	{id:"reset", eat:function(player){player.skills.reset(); player.stats.get("reset").tempBuff(1, 60);}},
	{id:"defense", eat:function(player){player.stats.get("defense").tempBuff(3, time);}},
	{id:"speed", eat:function(player){player.stats.get("speed").tempBuff(3, time);}}
];
function hasCafeteriaFood(player){
	for(s in player.stats) if(s.temp_buff_time > 0) return true; return false;
}
